package dev.zomboid.decor;
import java.util.*;import java.lang.reflect.Proxy;
public final class Climate {
 public static final Set<String> AIR=Set.of("aircondition","aircondition_2","airconditioning","airconditioning_2","centralairconditioning","centralairconditioning_2");
 static final Map<Object,Map<Object,Long>> ACTIVE=new WeakHashMap<>();static Object fan;static boolean reported;
 public static boolean air(String id){return AIR.contains(id);}
 public static boolean accepts(Object be,int slot,Object stack){return !air(Storage.id(R.call(be,"getBlockState")))&&Cooling.accepts(be,slot,stack);}
 public static Object ticker(Object level,Object state){if(!air(Storage.id(state)))return Cooling.ticker(level,state);if(R.yes(R.call(level,"isClientSide")))return null;Class<?> t=R.type("net.minecraft.world.level.block.entity.BlockEntityTicker");return Proxy.newProxyInstance(t.getClassLoader(),new Class[]{t},(p,m,a)->{switch(m.getName()){case "tick":tick(a[0],a[3]);return null;case "hashCode":return System.identityHashCode(p);case "equals":return p==a[0];default:return "Doomsday air conditioner";}});}
 static boolean power(Object world,Object p){
  try{Map<?,?> generators=(Map<?,?>)R.get(R.type("dev.zomboid.survival.MachineEntity"),"GENERATORS");Object registered=generators.get(world);if(!(registered instanceof Set<?> set))return false;
   for(Object q:set){if(!R.yes(R.call(world,"hasChunkAt",q))||distance(p,q)>625)continue;Object gen=R.call(world,"getBlockEntity",q);if(gen==null||!fuelled(gen))continue;Object energy=R.get(gen,"energy");if(((Number)R.call(energy,"extractEnergy",400,true)).intValue()!=400)continue;int actual=((Number)R.call(energy,"extractEnergy",400,false)).intValue();if(actual!=400)return false;R.call(gen,"setChanged");return true;}
  }catch(Exception ex){if(!reported){reported=true;System.err.println("[Doomsday AC] Generator unavailable: "+ex.getClass().getSimpleName());}}return false;
 }
 static boolean fuelled(Object generator){if(((Number)R.call(generator,"zsGetBurn")).intValue()>0)return true;int slots=((Number)R.call(generator,"getContainerSize")).intValue();Object smelting=R.get(R.type("net.minecraft.world.item.crafting.RecipeType"),"SMELTING");for(int i=0;i<slots;i++)if(((Number)R.call(R.call(generator,"getItem",i),"getBurnTime",smelting)).intValue()>0)return true;return false;}
 static double distance(Object a,Object b){double x=R.coord(a,"X")-R.coord(b,"X"),y=R.coord(a,"Y")-R.coord(b,"Y"),z=R.coord(a,"Z")-R.coord(b,"Z");return x*x+y*y+z*z;}
 public static void tick(Object world,Object be){long now=R.lng(R.call(world,"getGameTime"));if(now<R.lng(R.get(be,"ddNextTick")))return;R.set(be,"ddNextTick",now+20);Object p=R.call(be,"getBlockPos");Map<Object,Long> active=ACTIVE.computeIfAbsent(world,w->new HashMap<>());active.entrySet().removeIf(e->e.getValue()<now);boolean on=((Number)R.get(be,"ddIce")).intValue()>=0&&power(world,p);R.set(be,"ddChill",on?1:0);if(on){active.put(p,now+20);if(now%80==0&&fan!=null)R.call(world,"playSound",null,p,fan,R.get(R.type("net.minecraft.sounds.SoundSource"),"BLOCKS"),.35f,1f);}else active.remove(p);R.call(be,"setChanged");}
 public static boolean active(Object world,Object pos){Map<Object,Long> map=ACTIVE.get(world);if(map==null)return false;long now=R.lng(R.call(world,"getGameTime"));for(var e:map.entrySet()){Object p=e.getKey();if(e.getValue()<now||distance(pos,p)>225||!R.yes(R.call(world,"hasChunkAt",p)))continue;Object be=R.call(world,"getBlockEntity",p);if(be!=null&&air(Storage.id(R.call(be,"getBlockState")))&&((Number)R.get(be,"ddChill")).intValue()==1&&((Number)R.get(be,"ddIce")).intValue()>=0)return true;}return false;}
 public static void use(Object world,Object pos,Object player){if(R.yes(R.call(world,"isClientSide")))return;Object be=R.call(world,"getBlockEntity",pos);if(be==null)return;if(R.yes(R.call(player,"isShiftKeyDown"))){int off=((Number)R.get(be,"ddIce")).intValue();R.set(be,"ddIce",off<0?0:-1);R.set(be,"ddNextTick",0L);tick(world,be);R.call(world,"playSound",null,pos,R.get(R.type("net.minecraft.sounds.SoundEvents"),"LEVER_CLICK"),R.get(R.type("net.minecraft.sounds.SoundSource"),"BLOCKS"),.5f,off<0?1.2f:.8f);}String status=((Number)R.get(be,"ddIce")).intValue()<0?"off":((Number)R.get(be,"ddChill")).intValue()==1?"on":"no_power";R.call(player,"displayClientMessage",R.call(R.type("net.minecraft.network.chat.Component"),"translatable","message.doomsday_decoration.ac_"+status),true);R.call(be,"setChanged");}
 public static void register(Object e){Object key=R.get(R.type("net.minecraft.core.registries.Registries"),"SOUND_EVENT");if(!key.equals(R.call(e,"getRegistryKey")))return;Object id=R.call(R.type("net.minecraft.resources.ResourceLocation"),"fromNamespaceAndPath","doomsday_decoration","air_fan");fan=R.call(R.type("net.minecraft.sounds.SoundEvent"),"createVariableRangeEvent",id);R.call(e,"register",key,id,(java.util.function.Supplier<Object>)()->fan);}
 public static void grow(Object event){Object world=R.call(event,"getLevel"),pos=R.call(event,"getPos");if(!active(world,pos)||R.num(R.call(R.call(world,"getRandom"),"nextDouble"))>=.35)return;Object state=R.call(world,"getBlockState",pos),block=R.call(state,"getBlock");if(!R.type("net.minecraft.world.level.block.CropBlock").isInstance(block))return;int age=((Number)R.call(block,"getAge",state)).intValue(),max=((Number)R.call(block,"getMaxAge")).intValue();if(age<max)R.call(world,"setBlock",pos,R.call(state,"setValue",R.call(block,"getAgeProperty"),age+1),2);}
 public static void migrate(Object e){Object player=R.call(e,"getEntity"),world=R.call(player,"level");if(R.yes(R.call(world,"isClientSide"))||R.lng(R.call(world,"getGameTime"))%40!=0)return;Object origin=R.call(player,"blockPosition");for(int x=-5;x<=5;x++)for(int z=-5;z<=5;z++)for(int y=-3;y<=3;y++)Storage.repair(world,R.call(origin,"offset",x,y,z));}
 public static void homeoEnvironment(Object player,Object env){if(!active(R.call(player,"level"),R.call(player,"blockPosition")))return;float neutral=((Number)R.call(R.type("homeostatic.util.TempHelper"),"convertTemp",22.0,false)).floatValue();R.set(env,"airTemperature",neutral);R.set(env,"localTemperature",neutral);}
 public static void homeoBody(Object player,Object body){if(!active(R.call(player,"level"),R.call(player,"blockPosition")))return;float normal=((Number)R.get(R.get(R.type("homeostatic.common.temperature.TemperatureThreshold"),"NORMAL"),"temperature")).floatValue();for(String key:new String[]{"coreTemperature","skinTemperature","lastSkinTemperature"})R.set(body,key,normal);}
 public static boolean homeoData(Object player,Object data){if(!active(R.call(player,"level"),R.call(player,"blockPosition")))return false;float normal=((Number)R.get(R.get(R.type("homeostatic.common.temperature.TemperatureThreshold"),"NORMAL"),"temperature")).floatValue();for(String method:new String[]{"setCoreTemperature","setSkinTemperature","setLastSkinTemperature"})R.call(data,method,normal);return true;}
 public static boolean tan(Object player){Object world=R.call(player,"level");if(R.yes(R.call(world,"isClientSide"))||!active(world,R.call(player,"blockPosition")))return false;Object data=R.call(R.type("toughasnails.api.temperature.TemperatureHelper"),"getTemperatureData",player),neutral=R.get(R.type("toughasnails.api.temperature.TemperatureLevel"),"NEUTRAL");R.call(data,"setLevel",neutral);R.call(data,"setTargetLevel",neutral);R.call(data,"setHyperthermiaTicks",0);R.call(data,"setChangeDelayTicks",0);R.call(R.type("toughasnails.temperature.TemperatureHandler"),"removeHeatExhaustion",player);return true;}
}
